def get_model_persistence_order(model_name):
    cfg = load_model_config(model_name)
    if cfg is None:
        return [], []
    persistence = cfg.get("persistence", [])
    order = cfg.get("order", [])
    if not isinstance(persistence, list):
        persistence = []
    if not isinstance(order, list):
        order = []
    return persistence, order

def get_model_colors(model_name, is_svg=False):
    cfg = load_model_config(model_name)
    if cfg is None:
        return [], []
    key = "svg_colors" if is_svg else "terminal_colors"
    colors_cfg = cfg.get(key, {})
    matches = colors_cfg.get("matches", [])
    unknown = colors_cfg.get("unknown", ["white" if not is_svg else "gray"])
    return matches, unknown

def get_branches_and_tags(repo_path, local_only=False):
    branches = []
    result = subprocess.run(["git","for-each-ref","--format=%(refname) %(objectname)","refs/heads"], cwd=repo_path, capture_output=True, text=True)
    if result.stdout:
        for line in result.stdout.strip().splitlines():
            if not line: continue
            ref, hsh = line.split()
            name = ref.replace("refs/heads/","")
            branches.append((name, hsh, False, False))
    if not local_only:
        result = subprocess.run(["git","for-each-ref","--format=%(refname) %(objectname)","refs/remotes"], cwd=repo_path, capture_output=True, text=True)
        if result.stdout:
            for line in result.stdout.strip().splitlines():
                if not line: continue
                ref, hsh = line.split()
                name = ref.replace("refs/remotes/","")
                branches.append((name, hsh, True, False))
    result = subprocess.run(["git","for-each-ref","--format=%(refname) %(objectname) %(*objectname)","refs/tags"], cwd=repo_path, capture_output=True, text=True)
    tags = []
    if result.stdout:
        for line in result.stdout.strip().splitlines():
            if not line: continue
            parts = line.split()
            ref = parts[0]
            obj = parts[1]
            peeled = parts[2] if len(parts) > 2 else ""
            name = ref.replace("refs/tags/","")
            hsh = peeled if peeled else obj
            tags.append((name, hsh))
            branches.append((f"tags/{name}", hsh, False, True))
    head_branch = None
    head_hash = None
    result = subprocess.run(["git","rev-parse","--abbrev-ref","HEAD"], cwd=repo_path, capture_output=True, text=True)
    if result.stdout:
        abbrev = result.stdout.strip()
        if abbrev != "HEAD":
            head_branch = abbrev
        else:
            head_branch = "HEAD"
    result = subprocess.run(["git","rev-parse","HEAD"], cwd=repo_path, capture_output=True, text=True)
    if result.stdout:
        head_hash = result.stdout.strip()
    commit_to_refs = defaultdict(list)
    for name, hsh, is_remote, is_tag in branches:
        commit_to_refs[hsh].append((name, is_remote, is_tag))
    return branches, tags, commit_to_refs, head_branch, head_hash

