    result = subprocess.run(["git","show","-s","--pretty=format:"+fmt, commit_hash], cwd=repo_path, capture_output=True, text=True)
    if result.returncode != 0:
        return None
    out = result.stdout
    parts = out.split("\x00")
    while len(parts) < 18:
        parts.append("")
