def assign_branches(repo_path, commits, branches, tags, commit_to_refs, head_branch, head_hash, model_name, local_only):
    persistence, order = get_model_persistence_order(model_name)
    import re
    pers_regexes = []
    for pat in persistence:
        try:
            pers_regexes.append(re.compile(pat))
        except:
            pers_regexes.append(re.compile(re.escape(pat)))
    order_regexes = []
    for pat in order:
        try:
            order_regexes.append(re.compile(pat))
        except:
            order_regexes.append(re.compile(re.escape(pat)))
    def persistence_rank(name):
        for idx, rgx in enumerate(pers_regexes):
            if rgx.search(name):
                return idx
        return len(pers_regexes)
    def order_rank(name):
        for idx, rgx in enumerate(order_regexes):
            if rgx.search(name):
                return idx
        return len(order_regexes)
    branch_objs=[]
    for name, hsh, is_remote, is_tag in branches:
        pr = persistence_rank(name)
        ordr = order_rank(name)
        branch_objs.append({"name":name,"hash":hsh,"is_remote":is_remote,"is_tag":is_tag,"persistence_rank":pr,"order_rank":ordr,"commits":[],"range":(None,None)})
    branch_objs.sort(key=lambda b: (b["persistence_rank"], b["name"]))
    commit_index = {h:i for i,h in enumerate(commits)}
    parent_map={}
    cmd = ["git","rev-list","--all","--topo-order","--parents"]
    if local_only:
        cmd = ["git","rev-list","--branches","--tags","--topo-order","--parents"]
    result = subprocess.run(cmd, cwd=repo_path, capture_output=True, text=True)
    if result.returncode==0:
        for line in result.stdout.splitlines():
            parts=line.strip().split()
            if not parts: continue
            h=parts[0]; parents=parts[1:]
            parent_map[h]=parents
    assigned={}
    for b_idx, branch in enumerate(branch_objs):
        h=branch["hash"]
        if h not in commit_index:
            continue
        cur=h
        while cur and cur not in assigned:
            assigned[cur]=b_idx
            branch["commits"].append(cur)
            parents=parent_map.get(cur,[])
            if not parents:
                break
            first_parent=parents[0]
            if first_parent in assigned:
                break
            if first_parent not in commit_index:
                break
            cur=first_parent
    filtered_commits=[h for h in commits if h in assigned]
    filtered_index={h:i for i,h in enumerate(filtered_commits)}
    for b in branch_objs:
        if not b["commits"]:
            b["range"]=(None,None)
            continue
        f_indices=[filtered_index[h] for h in b["commits"] if h in filtered_index]
        if f_indices:
            b["range"]=(min(f_indices), max(f_indices))
        else:
            b["range"]=(None,None)
    return filtered_commits, assigned, branch_objs, parent_map, commit_to_refs, head_branch, head_hash

def sort_branches_for_display(branch_objs):
