    import re
    for pat, colors in matches:
        try:
            rgx=re.compile(pat)
        except:
            rgx=re.compile(re.escape(pat))
        if rgx.search(name):
            # colors is list
            if not colors:
                continue
            return colors[idx_in_match % len(colors)]
    # use unknown
