def expand_format_string(fmt, commit_data, refs_str):
    # Handle placeholders with modifiers: %[+ - space][...] plus placeholder
    # Placeholders list: H,h,P,p,d,s,b,B,an,ae,ad,as,ar,cn,ce,cd,cs,cr, n, % (escaped)
    # We need to parse fmt character by character
    # For %n we insert newline directly
