    # We'll handle: if placeholder not recognized, keep original "%x" as is.

    # Mapping of placeholder to function returning string (may be empty)
    placeholder_map = {
        "H": commit_data.get("H",""),
        "h": commit_data.get("h",""),
        "P": commit_data.get("P",""),
        "p": commit_data.get("p",""),
        "d": refs_str,
        "s": commit_data.get("s",""),
        "b": commit_data.get("b",""),
        "B": commit_data.get("B",""),
        "an": commit_data.get("an",""),
        "ae": commit_data.get("ae",""),
        "ad": commit_data.get("ad",""),
        "as": commit_data.get("as",""),
        "ar": commit_data.get("ar",""),
        "cn": commit_data.get("cn",""),
        "ce": commit_data.get("ce",""),
        "cd": commit_data.get("cd",""),
        "cs": commit_data.get("cs",""),
        "cr": commit_data.get("cr",""),
        "n": "\n",
        "%": "%",
    }
    # Longer placeholders first (2 chars) like an, ae, etc.
    # We'll parse.

    result = ""
    i=0
    n=len(fmt)
    # Keep track of pending newlines for %- handling? The spec for %-: delete all consecutive line-feeds immediately preceding the expansion if placeholder expands to empty.
    # The line-feeds are those in result that are at end? So before expanding placeholder, if placeholder is empty and has '-', we should strip trailing newlines from result.
    # For %+, insert newline before expansion if non-empty.
    # For % space, insert space before expansion if non-empty.
    while i < n:
        if fmt[i] != "%":
            result += fmt[i]
            i+=1
            continue
        # At %, check next char
        if i+1 >= n:
            result += "%"
            i+=1
            continue
        # Check for %% -> single %
        if fmt[i+1] == "%":
            result += "%"
            i+=2
            continue
        # Check for modifier + - or space after %
        modifier = None
        j = i+1
        if j < n and fmt[j] in ("+","-"," "):
            modifier = fmt[j]
            j+=1
            if j >= n:
                result += "%" + modifier
                i=j
                continue
        # Now at j, we have placeholder start
        # Try to match 2-char placeholders first: an, ae, ad, as, ar, cn, ce, cd, cs, cr
        # Also check for single char placeholders
        # We need to look ahead 2 chars
        matched = None
        # Check 2-char
        if j+1 < n:
            two = fmt[j:j+2]
            if two in ("an","ae","ad","as","ar","cn","ce","cd","cs","cr"):
                matched = two
                j+=2
            else:
                # Check single char
                c = fmt[j]
                if c in ("H","h","P","p","d","s","b","B","n"):
                    matched = c
                    j+=1
                else:
                    # Unknown placeholder, keep as is including % and modifier?
                    # Original keeps "%x" as literal
                    # If modifier present, original behavior? We saw earlier with "%+d" handling, but for unknown like "%a", it gave "%a" literal. What about "%+a"? Probably similar but not needed.
                    # We'll just output the original substring from i to j (including % and modifier and char)
                    result += fmt[i:j+1]  # include char
                    i=j+1
                    continue
        else:
            # Only one char left
            c = fmt[j]
            if c in ("H","h","P","p","d","s","b","B","n"):
                matched = c
                j+=1
            else:
                result += fmt[i:j+1]
                i=j+1
                continue
        if matched is None:
            # Unknown, output as is
            result += fmt[i:j]
            i=j
            continue
        # Now we have matched placeholder and modifier
        expansion = placeholder_map.get(matched, "")
        # Handle modifier
        if modifier == "+":
            if expansion != "":
                # Insert newline before expansion if not already? Spec says line-feed inserted immediately before expansion
                # We should add "\n" before expansion
                # But what about result already ending with newline? We'll just add newline
                result += "\n" + expansion
            else:
                # If empty, add nothing (and don't add newline)
                pass
        elif modifier == "-":
            if expansion == "":
                # Delete all consecutive line-feeds immediately preceding expansion
                # Strip trailing \n from result
                while result.endswith("\n"):
                    result = result[:-1]
                # Do not add expansion (since empty)
            else:
                result += expansion
        elif modifier == " ":
            if expansion != "":
                result += " " + expansion
            else:
                # Do not add space
                pass
        else:
            result += expansion
        i=j
    return result

